/*example :wap in cpp to illustrate the concept of reinterpret_cast operator using tow diffreent classes*/
#include<iostream>using namespace std; class Complex{float real, img;public:void  getdata(){cout<<"enter a complex number"<<endl;cin>>real>>img;}void showData(){cout <<real<<"+i"<<img<<endl;} }; class Distance{float feet, inch;public:void getData(){cout <<"enter a distance:"<<endl;cin>>feet>>inch;}void showData(){cout <<feet<< "feet"<<inch<<"inches"<<endl;} };int main(){Complex *cptr= new Complex;Distance *dptr= new Distance;dptr -> getData();cptr=reinterpret_cast<Complex *> (dptr);cptr->showData();delete dptr,cptr;return 0;}